using GaoApp.Web.Services.Assistant;
using GaoApp.Web.Services.CustomerService;
using Xunit;
namespace GaoApp.Tests.Security;
public sealed class CustomerQualityStoreTests:IDisposable
{
    private readonly string dir=Path.Combine(Path.GetTempPath(),"GaoQualityTests",Guid.NewGuid().ToString("N"));
    private readonly AssistantIntegrationTests.FixedClock clock=new();
    private CustomerServiceStore Store()=>new(new AssistantIntegrationTests.EnvironmentStub(dir),new AssistantIntegrationTests.Monitor<CustomerServiceOptions>(new(){DatabasePath="quality.db"}),clock);
    private static readonly CustomerStaff Manager=new(1,1,"TEST quản lý",true,true),Staff=new(2,1,"TEST nhân viên",true,false);
    private readonly Guid visitor=Guid.NewGuid();
    private CustomerConversation Answer(CustomerServiceStore s,int store=1){var settings=s.Settings(store);if(!settings.Enabled)s.Configure(store,true,settings.Version);var c=s.Start(store,visitor,new(Guid.NewGuid(),"TEST khách","PRIVATE CONTACT NOT IN EVALUATION",true));return More(s,c);}
    private CustomerConversation More(CustomerServiceStore s,CustomerConversation c){var request=Guid.NewGuid();s.Begin(c.StoreId,visitor,c.Id,new(request,"PRIVATE câu hỏi <img src=x onerror=alert(1)>"));return s.Complete(new(visitor,c.StoreId,c.Id,request),"TEST câu trả lời","{}",null);}
    private static Guid Message(CustomerConversation c)=>c.Messages.Last(m=>m.Role=="assistant").Id;
    [Fact]public void No_feedback_is_unknown_not_a_perfect_score(){var s=Store();Answer(s);var report=s.QualityReport(Manager,7,"all");Assert.Equal(1,report.Conversations);Assert.Equal(0,report.CustomerVotes);Assert.Null(report.HelpfulCustomerRate);Assert.Empty(s.QualityQueue(Manager,7,"all","open").Items);}
    [Fact]public void Customer_and_staff_votes_are_separate_and_retry_does_not_inflate_counts(){var s=Store();var c=Answer(s);var input=new CustomerRating(Guid.NewGuid(),Message(c),"helpful");s.RateCustomer(1,visitor,c.Id,input);s.RateCustomer(1,visitor,c.Id,input);s.RateStaff(Staff,c.Id,new(Guid.NewGuid(),Message(c),"wrong_product"));Assert.Equal("helpful",Assert.Single(s.CustomerVotes(1,visitor,c.Id)).Kind);Assert.Equal("wrong_product",Assert.Single(s.StaffVotes(Staff,c.Id)).Kind);Assert.Empty(s.StaffVotes(Manager,c.Id));var report=s.QualityReport(Manager,7,"web");Assert.Equal(1,report.CustomerVotes);Assert.Equal(1,report.StaffVotes);Assert.Equal(1d,report.HelpfulCustomerRate);Assert.Equal(1,report.OpenIssues);Assert.Equal("staff",Assert.Single(s.QualityQueue(Manager,7,"all","open").Items).ActorType);}
    [Theory][InlineData("helpful")][InlineData("wrong_product")][InlineData("wrong_price")][InlineData("unclear")][InlineData("wrong_policy")][InlineData("other")]
    public void Feedback_is_per_answer_and_can_be_removed_without_a_late_retry_restoring_it(string kind){var s=Store();var c=Answer(s);var input=new CustomerRating(Guid.NewGuid(),Message(c),kind);s.RateCustomer(1,visitor,c.Id,input);Assert.Single(s.CustomerVotes(1,visitor,c.Id));s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),null));Assert.Empty(s.CustomerVotes(1,visitor,c.Id));s.RateCustomer(1,visitor,c.Id,input);Assert.Empty(s.CustomerVotes(1,visitor,c.Id));}
    [Fact]public void Only_assistant_messages_in_owned_store_and_visitor_can_be_rated(){var s=Store();var c=Answer(s);var input=new CustomerRating(Guid.NewGuid(),Message(c),"unclear");Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.RateCustomer(2,visitor,c.Id,input)).Status);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.RateCustomer(1,Guid.NewGuid(),c.Id,input)).Status);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.RateStaff(Staff with{StoreId=2},c.Id,input)).Status);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.RateCustomer(1,visitor,c.Id,input with{MessageId=c.Messages.Single(m=>m.Role=="customer").Id})).Status);Assert.Equal(403,Assert.Throws<AssistantException>(()=>s.RateStaff(Staff with{CanReply=false},c.Id,input)).Status);}
    [Fact]public void Changed_payload_with_same_request_is_conflict_and_bad_kind_is_rejected(){var s=Store();var c=Answer(s);var input=new CustomerRating(Guid.NewGuid(),Message(c),"unclear");s.RateCustomer(1,visitor,c.Id,input);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.RateCustomer(1,visitor,c.Id,input with{Kind="wrong_price"})).Status);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.RateCustomer(1,visitor,c.Id,input with{Kind="<script>"})).Status);}
    [Fact]public void Review_is_versioned_idempotent_and_a_new_customer_issue_reopens_it(){var s=Store();var c=Answer(s);s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),"unclear"));var row=Assert.Single(s.QualityQueue(Manager,7,"all","open").Items);Assert.Equal("customer",row.ActorType);Assert.Contains("PRIVATE",row.Question);var command=new CustomerQualityReview(Guid.NewGuid(),row.Version,"resolve","language");var reviewed=s.ReviewQuality(Manager,row.Id,command);Assert.Equal("resolved",reviewed.Status);Assert.Equal(reviewed.Version,s.ReviewQuality(Manager,row.Id,command).Version);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.ReviewQuality(Manager,row.Id,command with{RequestId=Guid.NewGuid()})).Status);s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),"unclear"));Assert.Equal("resolved",s.QualityItem(Manager,row.Id).Status);s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),"wrong_product"));row=s.QualityItem(Manager,row.Id);Assert.Equal("open",row.Status);Assert.Null(row.Resolution);Assert.Null(row.ReviewedBy);Assert.NotEqual(reviewed.Version,row.Version);}
    [Fact]public void Management_and_foreign_store_cannot_be_inferred_from_browser_ids(){var s=Store();var c=Answer(s);s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),"wrong_price"));var row=Assert.Single(s.QualityQueue(Manager,7,"all","open").Items);Assert.Equal(403,Assert.Throws<AssistantException>(()=>s.QualityReport(Staff,7,"all")).Status);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.QualityItem(Manager with{StoreId=2},row.Id)).Status);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.QualityReport(Manager,30,"all")).Status);Assert.Equal(400,Assert.Throws<AssistantException>(()=>s.QualityReport(Manager,7,"unknown")).Status);Assert.Empty(s.QualityQueue(Manager,7,"facebook","all").Items);}
    [Fact]public void Feedback_survives_recycle_but_cascades_with_expired_transcript(){var s=Store();var c=Answer(s);s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),"wrong_price"));Assert.Single(Store().QualityQueue(Manager,7,"all","all").Items);clock.Now=clock.Now.AddDays(2);Assert.Equal(0,Store().QualityReport(Manager,1,"all").CustomerVotes);Assert.Equal(1,Store().QualityReport(Manager,7,"all").CustomerVotes);clock.Now=clock.Now.AddDays(6);Store().Purge();Assert.Empty(Store().QualityQueue(Manager,7,"all","all").Items);Assert.Null(Store().QualityReport(Manager,7,"all").HelpfulCustomerRate);}
    [Fact]public void Queue_pages_are_stable_and_do_not_duplicate_rows(){var s=Store();var c=Answer(s);for(var i=0;i<55;i++){if(i>0)c=More(s,c);s.RateCustomer(1,visitor,c.Id,new(Guid.NewGuid(),Message(c),"unclear"));}var first=s.QualityQueue(Manager,7,"all","open");var second=s.QualityQueue(Manager,7,"all","open",1);Assert.Equal(50,first.Items.Length);Assert.True(first.HasMore);Assert.Equal(5,second.Items.Length);Assert.False(second.HasMore);Assert.Empty(first.Items.Select(r=>r.Id).Intersect(second.Items.Select(r=>r.Id)));}
    public void Dispose(){if(Directory.Exists(dir))Directory.Delete(dir,true);}
}
